export const RECORD_TEXT =
  "{path} is a lodge record file, and lodge owns it: do not edit it by hand. Run `lodge draft REF` (or `lodge draft area:NAME`) to get it as a draft outside `lodge/`, edit the draft, check it with `lodge add --dry-run FILE`, then publish it with `lodge add FILE`. Reverse your own edit now: put back exactly the text you replaced, with the same tool. Do not run `git checkout`, `git restore`, `git stash`, or `git clean` on this file, since they also discard changes that are not yours. If you cannot restore it exactly, tell the author.";
export const THREAD_TEXT =
  "{path} is a lodge thread file, and lodge owns it: do not edit it by hand. Add a message with `lodge reply Q --by ROLE FILE`, or close it with `lodge close Q --by ROLE`. Reverse your own edit now: put back exactly the text you replaced, with the same tool. Do not run `git checkout`, `git restore`, `git stash`, or `git clean` on this file, since they also discard changes that are not yours. If you cannot restore it exactly, tell the author.";
export const FROZEN_TEXT =
  "{path} is frozen: lodge holds its content now, so do not edit it. Record the change as a new decision instead: write a draft (`lodge guide` shows the draft format), check it with `lodge add --dry-run FILE`, then publish it with `lodge add FILE`. If the author asked for this edit, tell her the file is frozen and ask before reversing it. Otherwise reverse your own edit now: put back exactly the text you replaced, with the same tool. Do not run `git checkout`, `git restore`, `git stash`, or `git clean` on this file, since they also discard changes that are not yours. If you cannot restore it exactly, tell the author.";
export const MOVED_RECORD_TEXT =
  "{path} is a lodge record file from before this project moved to the lodge server at {server}: its records live on the server now, and an edit here changes nothing there. Run `lodge draft REF` (or `lodge draft area:NAME`) to get the record as a draft, edit the draft, check it with `lodge add --dry-run FILE`, then publish it with `lodge add FILE`; the command sends both to the server. Reverse your own edit now: put back exactly the text you replaced, with the same tool. Do not run `git checkout`, `git restore`, `git stash`, or `git clean` on this file, since they also discard changes that are not yours. If you cannot restore it exactly, tell the author.";
